<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Str;

class IntegrationController extends Controller {
 private function configs(int $c):array{$rows=DB::table('settings')->where(['company_id'=>$c,'group'=>'integration_credentials'])->get();$out=[];foreach($rows as $r){try{$out[$r->key]=json_decode(Crypt::decryptString($r->value),true);}catch(\Throwable){$out[$r->key]=[];}}return $out;}
 private function log(Request $r,string $provider,string $operation,string $status,$requestData=null,$responseData=null,$error=null):void{DB::table('integration_logs')->insert(['company_id'=>$r->user()->company_id,'provider'=>$provider,'operation'=>$operation,'status'=>$status,'request_data'=>$requestData?json_encode($requestData):null,'response_data'=>$responseData?json_encode($responseData):null,'error'=>$error,'created_at'=>now(),'updated_at'=>now()]);}
 public function status(Request $r){$c=$r->user()->company_id;$cfg=$this->configs($c);return response()->json(['success'=>true,'data'=>['providers'=>collect(['sunat','whatsapp','email','webhook','api'])->map(fn($p)=>['provider'=>$p,'configured'=>$p==='api'?DB::table('integration_api_tokens')->where(['company_id'=>$c,'status'=>'active'])->exists():!empty($cfg[$p])])->values(),'api_tokens'=>DB::table('integration_api_tokens')->where('company_id',$c)->select('id','name','abilities','last_used_at','expires_at','status','created_at')->latest()->get(),'logs'=>DB::table('integration_logs')->where('company_id',$c)->latest()->limit(100)->get()]]);}
 public function configure(Request $r,string $provider){abort_unless(in_array($provider,['sunat','whatsapp','email','webhook']),404);$data=$r->validate(['config'=>'required|array'])['config'];if($provider==='webhook'){abort_unless(isset($data['url'])&&is_string($data['url']),422,'Indica la URL del webhook');app(\App\Services\PublicWebhookUrl::class)->validate($data['url']);}DB::table('settings')->updateOrInsert(['company_id'=>$r->user()->company_id,'group'=>'integration_credentials','key'=>$provider],['value'=>Crypt::encryptString(json_encode($data)),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Credenciales guardadas de forma cifrada']);}
 public function test(Request $r,string $provider){$cfg=$this->configs($r->user()->company_id)[$provider]??[];abort_unless($cfg,422,'Configura primero las credenciales');try{$result=match($provider){'webhook'=>$this->webhook($cfg),'whatsapp'=>$this->whatsapp($cfg),'sunat'=>$this->sunat($cfg),'email'=>$this->email($cfg),default=>abort(404)};$this->log($r,$provider,'connection_test','completed',['target'=>$cfg['url']??$cfg['recipient']??null],$result);return response()->json(['success'=>true,'message'=>'Conexión verificada','data'=>$result]);}catch(\Throwable $e){$this->log($r,$provider,'connection_test','failed',null,null,$e->getMessage());abort(422,$e->getMessage());}}
 public function createApiToken(Request$r){$d=$r->validate(['name'=>'required|max:100','abilities'=>'nullable|array','expires_at'=>'nullable|date|after:now']);$plain='dst_'.Str::random(56);$id=DB::table('integration_api_tokens')->insertGetId(['company_id'=>$r->user()->company_id,'user_id'=>$r->user()->id,'name'=>$d['name'],'token_hash'=>hash('sha256',$plain),'abilities'=>json_encode($d['abilities']??['read']),'expires_at'=>$d['expires_at']??null,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);$this->log($r,'api','token.created','completed',['token_id'=>$id,'name'=>$d['name']]);return response()->json(['success'=>true,'message'=>'Token creado; cópialo ahora porque no se volverá a mostrar','data'=>['id'=>$id,'token'=>$plain]],201);}
 public function revokeApiToken(Request$r,int$id){DB::table('integration_api_tokens')->where(['id'=>$id,'company_id'=>$r->user()->company_id])->update(['status'=>'revoked','updated_at'=>now()]);$this->log($r,'api','token.revoked','completed',['token_id'=>$id]);return response()->json(['success'=>true,'message'=>'Token revocado']);}
 private function webhook(array $c):array{app(\App\Services\PublicWebhookUrl::class)->validate((string)($c['url']??''));$headers=($c['secret']??null)?['X-Deurstore-Secret'=>$c['secret']]:[];$r=Http::connectTimeout(5)->timeout(10)->withoutRedirecting()->withHeaders($headers)->post($c['url'],['event'=>'integration.test','timestamp'=>now()->toIso8601String()]);$r->throw();return['status'=>$r->status(),'body'=>substr($r->body(),0,1000)];}
 private function whatsapp(array $c):array{$r=Http::timeout(30)->withToken($c['token'])->post("https://graph.facebook.com/v21.0/{$c['phone_number_id']}/messages",['messaging_product'=>'whatsapp','to'=>$c['recipient'],'type'=>'text','text'=>['body'=>'Prueba de integración Deurstore ERP']]);$r->throw();return$r->json();}
 private function sunat(array $c):array{$url="https://api-seguridad.sunat.gob.pe/v1/clientessol/{$c['client_id']}/oauth2/token/";$r=Http::asForm()->timeout(30)->post($url,['grant_type'=>'password','scope'=>'https://api-cpe.sunat.gob.pe','client_id'=>$c['client_id'],'client_secret'=>$c['client_secret'],'username'=>$c['username'],'password'=>$c['password']]);$r->throw();return['authenticated'=>true,'expires_in'=>$r->json('expires_in')];}
 private function email(array $c):array{config(['mail.default'=>'smtp','mail.mailers.smtp.host'=>$c['host'],'mail.mailers.smtp.port'=>$c['port']??587,'mail.mailers.smtp.username'=>$c['username'],'mail.mailers.smtp.password'=>$c['password'],'mail.mailers.smtp.encryption'=>$c['encryption']??'tls','mail.from.address'=>$c['from_address'],'mail.from.name'=>$c['from_name']??'Deurstore']);Mail::raw('Correo de prueba enviado por Deurstore ERP.',fn($m)=>$m->to($c['recipient'])->subject('Prueba de integración Deurstore'));return['sent'=>true,'recipient'=>$c['recipient']];}
}
